cd /tmp/work; mm singlecell python -c "
import pandas as pd, numpy as np
from scipy import stats
pd.set_option('display.width', 250); pd.set_option('display.max_columns', 50); pd.set_option('display.max_rows', 500)
w = pd.read_parquet('wide_logFC.parquet'); wp = pd.read_parquet('wide_adjP.parquet'); wse = pd.read_parquet('wide_SE.parquet')
def comps(t4,t5):
    IV = w[t4]; ICI = w[f'Compound_47_IL33_vs_IL33_HUVEC_{t5}']; ICIN = w[f'Compound_47_IL33_vs_IL33_NIP228_HUVEC_{t5}']
    return dict(IV=IV, ICI=ICI, ICIN=ICIN, INI=ICI-ICIN, ICV=ICI+IV, INV=ICI-ICIN+IV)
c6 = comps('IL33_vs_Nontreated_HUVEC_6_hrs','6hrs'); c24 = comps('IL33_vs_Nontreated_HUVEC_24_hrs','24hrs')
p6 = wp['IL33_vs_Nontreated_HUVEC_6_hrs']; p24 = wp['IL33_vs_Nontreated_HUVEC_24_hrs']
for selname, selc, selp, evname, ev in [('6h',c6,p6,'24h',c24),('24h',c24,p24,'6h',c6)]:
    for d,sel in [('up',(selc['IV']>1)&(selp<0.05)),('down',(selc['IV']<-1)&(selp<0.05))]:
        print(f'select {d} at {selname} (n={sel.sum()}), evaluate at {evname}:')
        for k in ['IV','ICIN','ICV','INI','INV']:
            print(f'     median {k}: {ev[k][sel].median():.3f}')
        # fraction of IL-33 response at eval time neutralised, among genes that also respond at eval time
        x = ev['IV'][sel]; 
        print('     eval-time slope ICIN~IV: %.3f' % stats.linregress(x, ev['ICIN'][sel]).slope)
"

